+    let repository = CaldavRepository::new(accounts.pool().clone());
+    let event_ids = match repository
+        .list_events_in_range(
+            calendar.calendar_id,
+            cal_query.start_utc,
+            cal_query.end_utc,
+            MAX_RESULTS,
