+    accounts: &CaldavAccountService,
+    principal_id: &str,
+    calendar: &CaldavCalendar,
+    multiget: &CalendarMultiget,
+) -> Response {
+    let Some(access) = read_access_for_role(&calendar.role) else {
+        return dav_calendar_not_found();
+    };
